<section class="page-head"><div><h1>Discounts</h1><p>Manage one-code offers on merchandise. Shipping is excluded.</p></div><a class="btn btn-primary" href="#discount-editor">Create discount</a></section>
<?php if($errors): ?><div class="alert alert-error" role="alert" data-error-summary tabindex="-1"><strong>Please review the discount.</strong><ul><?php foreach($errors as $message): ?><li><?= e(is_string($message)?$message:'Check the highlighted fields.') ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<form method="get" action="<?= e(url('/catalog/discounts')) ?>" class="management-filters"><label class="field"><span>Search codes</span><input name="q" maxlength="80" value="<?= e($list['q']) ?>"></label><label class="field"><span>Status</span><select name="status"><option value="">All statuses</option><?php foreach(['active','inactive','archived'] as $status): ?><option value="<?= $status ?>" <?= $list['status']===$status?'selected':'' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></label><button class="btn btn-secondary" type="submit">Filter</button><a href="<?= e(url('/catalog/discounts')) ?>">Reset</a></form>
<div class="table-wrap"><table><thead><tr><th>Code</th><th>Discount</th><th>Status</th><th>Validity</th><th>Uses / limit</th><th>Actions</th></tr></thead><tbody>
<?php foreach($list['items'] as $row): ?><tr><td><strong><?= e($row['code']) ?></strong><small class="muted"><?= e($row['description']) ?></small></td><td><?= $row['kind']==='percentage'?e(\App\Services\ShippingService::decimal((int)$row['value_units'])).'%':'₱'.e(\App\Services\ShippingService::decimal((int)$row['value_units'])) ?><small>Minimum ₱<?= e(\App\Services\ShippingService::decimal((int)$row['minimum_cents'])) ?></small></td><td><?= staff_status($row['status']) ?></td><td><?= e($row['starts_at']??'Available now') ?><br><?= e($row['expires_at']??'No expiry') ?></td><td><?= (int)$row['uses_total'] ?> / <?= $row['usage_limit']!==null?(int)$row['usage_limit']:'Unlimited' ?><small>Per customer: <?= $row['customer_limit']!==null?(int)$row['customer_limit']:'Unlimited' ?></small></td><td><div class="table-actions">
<?php if($row['status']!=='archived'): ?><a class="btn btn-secondary btn-sm" href="<?= e(url('/catalog/discounts?edit='.(int)$row['id'].'#discount-editor')) ?>">Edit</a>
<?php foreach([$row['status']==='active'?'deactivate':'activate'=>'Status','remove'=>'Remove'] as $action=>$label): ?><form method="post" action="<?= e(url('/catalog/discounts')) ?>" <?= $action==='remove'?'data-confirm="Remove this unused discount, or archive it if it has order history?"':'' ?>><?= csrf_field() ?><input type="hidden" name="action" value="<?= e($action) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><input type="hidden" name="revision" value="<?= e($row['revision']) ?>"><button type="submit" class="btn btn-secondary btn-sm"><?= e($action==='remove'?'Remove':ucfirst($action)) ?></button></form><?php endforeach; ?>
<?php else: ?><span class="muted">History preserved</span><?php endif; ?></div></td></tr><?php endforeach; ?>
<?php if(!$list['items']): ?><tr><td colspan="6">No discounts match these filters.</td></tr><?php endif; ?></tbody></table></div>
<?= pagination_nav((int)$list['page'],(int)$list['pages'],static fn(int $n):string=>url('/catalog/discounts?'.http_build_query(['q'=>$list['q'],'status'=>$list['status'],'page'=>$n])),'Discount pages') ?>
<section class="management-editor" id="discount-editor"><h2><?= $editing?'Edit discount':'Create discount' ?></h2><details class="staff-help"><summary>How discount rules work</summary><p>Applies to all eligible products before shipping. Values and dates use Philippine local time. Pending card orders hold a use until their payment is confirmed or fails.</p></details>
<form method="post" action="<?= e(url('/catalog/discounts')) ?>" class="discount-form"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)$editId ?>"><input type="hidden" name="revision" value="<?= e($editing['revision']??'') ?>">
<?php foreach(['code'=>['Code',32],'description'=>['Internal description (optional)',255],'value'=>['Value: percent or PHP',12],'minimum'=>['Minimum merchandise subtotal (optional)',12],'usage_limit'=>['Total usage limit (optional)',7],'customer_limit'=>['Per-customer limit (optional)',7]] as $field=>[$label,$max]): ?><label class="field"><span><?= e($label) ?></span><input name="<?= e($field) ?>" maxlength="<?= $max ?>" value="<?= e(is_scalar($values[$field]??'')?(string)($values[$field]??''):'') ?>" <?= in_array($field,['code','value'],true)?'required':'' ?> <?= in_array($field,['value','minimum','usage_limit','customer_limit'],true)?'inputmode="decimal"':'' ?> aria-invalid="<?= isset($errors[$field])?'true':'false' ?>"></label><?php endforeach; ?>
<label class="field"><span>Discount type</span><select name="kind"><option value="percentage" <?= ($values['kind']??'percentage')==='percentage'?'selected':'' ?>>Percentage</option><option value="fixed" <?= ($values['kind']??'')==='fixed'?'selected':'' ?>>Fixed amount (PHP)</option></select></label>
<label class="field"><span>Status</span><select name="status"><option value="inactive" <?= ($values['status']??'inactive')==='inactive'?'selected':'' ?>>Inactive</option><option value="active" <?= ($values['status']??'')==='active'?'selected':'' ?>>Active</option></select></label>
<?php foreach(['starts_at'=>'Starts (optional)','expires_at'=>'Expires (optional)'] as $field=>$label): $date=is_string($values[$field]??null)?str_replace(' ','T',substr($values[$field],0,16)):''; ?><label class="field"><span><?= e($label) ?></span><input type="datetime-local" name="<?= e($field) ?>" value="<?= e($date) ?>"></label><?php endforeach; ?>
<div class="form-actions"><button type="submit" class="btn btn-primary">Save discount</button><a class="btn btn-secondary" href="<?= e(url('/catalog/discounts')) ?>">Cancel</a></div></form></section>
